import { PUZZLES_PER_THEME } from '../core/levels';
import { themeById } from '../data/words';

export type Route =
  | { name: 'home' }
  | { name: 'puzzle'; themeId: string; index: number };

/** Parse the current location.hash into a route; unknown/invalid → home. */
export function parseHash(): Route {
  const m = /^#\/p\/([^/]+)\/(\d+)$/.exec(window.location.hash);
  if (!m) return { name: 'home' };
  const themeId = decodeURIComponent(m[1]);
  const index = Number(m[2]);
  if (!themeById(themeId) || index < 1 || index > PUZZLES_PER_THEME) return { name: 'home' };
  return { name: 'puzzle', themeId, index };
}

export function navigate(hash: string): void {
  window.location.hash = hash;
}

export function onRoute(cb: (route: Route) => void): void {
  const handler = () => cb(parseHash());
  window.addEventListener('hashchange', handler);
  handler();
}
