{"content":"import { defaultSave, parseSave, serializeSave } from '../core/save';
import type { SaveState } from '../core/types';

const KEY = 'cp.save.v1';

let current: SaveState = defaultSave();
let loaded = false;

/** Read the save from localStorage into the in-memory instance. Falls back to the default on failure. */
export function loadSave(): SaveState {
  try {
    current = parseSave(localStorage.getItem(KEY));
  } catch {
    current = defaultSave();
  }
  loaded = true;
  return current;
}

/** The single in-memory SaveState the UI mutates (loads it on first use). */
export function getSave(): SaveState {
  if (!loaded) return loadSave();
  return current;
}

/** Persist `s` and adopt it as the in-memory instance; a storage failure never crashes the app. */
export function saveState(s: SaveState): void {
  current = s;
  try {
    localStorage.setItem(KEY, serializeSave(s));
  } catch {
    // storage unavailable (private mode / quota) — keep the in-memory copy
  }
}
