import { letterAt } from '../core/generate';

export const MIN_CELL = 28;
export const MAX_CELL = 56;
const SVG_NS = 'http://www.w3.org/2000/svg';

export interface GridView {
  paper: HTMLDivElement;
  grid: HTMLDivElement;
  svg: SVGSVGElement;
  found: SVGGElement;
  active: SVGLineElement;
  cellEls: HTMLDivElement[];
  cell: number; // current cell size in px
}

function svgEl(name: 'svg' | 'g' | 'line'): SVGSVGElement | SVGGElement | SVGLineElement {
  return document.createElementNS(SVG_NS, name) as SVGSVGElement | SVGGElement | SVGLineElement;
}

/** Build the `.grid-paper > .grid > svg.overlay + .cells` DOM for `puzzle` (unsized). */
export function buildGrid(puzzle: Puzzle): GridView {
  const paper = document.createElement('div');
  paper.className = 'grid-paper';
  const grid = document.createElement('div');
  grid.className = 'grid';
  grid.setAttribute('role', 'grid');
  const svg = svgEl('svg') as SVGSVGElement;
  svg.setAttribute('class', 'overlay');
  svg.setAttribute('aria-hidden', 'true');
  const found = svgEl('g') as SVGGElement;
  found.setAttribute('class', 'found');
  const active = svgEl('line') as SVGLineElement;
  active.setAttribute('class', 'active');
  active.style.display = 'none';
  svg.append(found, active);
  const cells = document.createElement('div');
  cells.className = 'cells';
  const cellEls: HTMLDivElement[] = [];
  for (let r = 0; r < puzzle.rows; r++) {
    for (let c = 0; c < puzzle.cols; c++) {
      const el = document.createElement('div');
      el.className = 'cell';
      el.dataset.r = String(r);
      el.dataset.c = String(c);
      el.textContent = letterAt(puzzle, { row: r, col: c });
      cells.appendChild(el);
      cellEls.push(el);
    }
  }
  grid.append(svg, cells);
  paper.appendChild(grid);
  return { paper, grid, svg, found, active, cellEls, cell: MIN_CELL };
}

/**
 * Compute the cell size from the available box (content box of `.grid-area`
 * minus the paper padding), apply it to the DOM and re-draw all pills.
 * Returns the cell size in px.
 */
export function sizeGrid(view: GridView, puzzle: Puzzle, found: FoundWord[], availW: number, availH: number): number {
  if (availW <= 0 || availH <= 0) return view.cell;
  const cell = Math.min(MAX_CELL, Math.max(MIN_CELL, Math.floor(Math.min(availW / puzzle.cols, availH / puzzle.rows))));
  view.cell = cell;
  const w = cell * puzzle.cols;
  const h = cell * puzzle.rows;
  view.grid.style.setProperty('--cell', `${cell}px`);
  view.grid.style.setProperty('--cols', String(puzzle.cols));
  view.grid.style.width = `${w}px`;
  view.grid.style.height = `${h}px`;
  view.svg.setAttribute('width', String(w));
  view.svg.setAttribute('height', String(h));
  view.svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  redrawPills(view, found);
  return cell;
}

/** Position one pill `<line>` on the cell centers, first to last. */
function pillLine(view: GridView, cells: Cell[]): SVGLineElement {
  const first = cells[0];
  const last = cells[cells.length - 1];
  const line = svgEl('line') as SVGLineElement;
  line.setAttribute('x1', String((first.col + 0.5) * view.cell));
  line.setAttribute('y1', String((first.row + 0.5) * view.cell));
  line.setAttribute('x2', String((last.col + 0.5) * view.cell));
  line.setAttribute('y2', String((last.row + 0.5) * view.cell));
  line.setAttribute('stroke-width', String(view.cell * 0.78));
  line.setAttribute('stroke-linecap', 'round');
  return line;
}

/** Re-draw every found pill (recomputed from cells, the SVG is never scaled). */
export function redrawPills(view: GridView, found: FoundWord[]): void {
  const lines = found.map((f) => {
    const line = pillLine(view, f.cells);
    line.setAttribute('class', `pill p${f.colorIndex % 8}`);
    return line;
  });
  view.found.replaceChildren(...lines);
}

/** Move the active drag pill to the current selection (show it if hidden). */
export function setActivePill(view: GridView, cells: Cell[]): void {
  const first = cells[0];
  const last = cells[cells.length - 1];
  view.active.setAttribute('x1', String((first.col + 0.5) * view.cell));
  view.active.setAttribute('y1', String((first.row + 0.5) * view.cell));
  view.active.setAttribute('x2', String((last.col + 0.5) * view.cell));
  view.active.setAttribute('y2', String((last.row + 0.5) * view.cell));
  view.active.setAttribute('stroke-width', String(view.cell * 0.78));
  view.active.style.display = '';
}
