{"content":"import type { FoundWord, Placement, Puzzle, Theme } from '../core/types';
import { pathCells } from '../core/directions';
import { GenerationError, generatePuzzle } from '../core/generate';
import { PUZZLES_PER_THEME } from '../core/levels';
import { themeById } from '../data/words';
import { getSave, saveState } from './storage';
import { buildGrid, redrawPills, sizeGrid, type GridView } from './grid';
import { navigate } from './router';
import { STR } from './strings';

const SEED_SUFFIXES = ['', ':1', ':2', ':3', ':4', ':5'];

/** Generate the puzzle, retrying with suffixes ':1'..':5' on GenerationError; rethrows if all fail. */
function buildPuzzle(theme: Theme, index: number): Puzzle {
  let lastErr: unknown;
  for (const suffix of SEED_SUFFIXES) {
    try {
      return generatePuzzle(theme, index, suffix);
    } catch (err) {
      lastErr = err;
    }
  }
  throw lastErr instanceof GenerationError ? lastErr : new GenerationError(`Could not generate ${theme.id}:${index}`);
}

let observer: ResizeObserver | null = null;

export function renderPuzzle(themeId: string, index: number): HTMLElement {
  const theme = themeById(themeId)!;
  const puzzle = buildPuzzle(theme, index);

  const root = document.createElement('div');
  root.className = 'puzzle';

  const head = document.createElement('header');
  head.className = 'puzzle-head';
  const back = document.createElement('button');
  back.className = 'icon-btn back';
  back.setAttribute('aria-label', STR.back);
  back.textContent = '‹';
  back.addEventListener('click', () => navigate('#/'));
  const title = document.createElement('div');
  title.className = 'title';
  const strong = document.createElement('strong');
  strong.textContent = theme.name;
  const span = document.createElement('span');
  span.textContent = STR.phase(index, PUZZLES_PER_THEME);
  title.append(strong, span);
  head.append(back, title);

  const trace = document.createElement('div');
  trace.className = 'trace';
  trace.setAttribute('aria-live', 'polite');

  const area = document.createElement('div');
  area.className = 'grid-area';
  const view = buildGrid(puzzle);
  area.appendChild(view.paper);

  const words = document.createElement('div');
  words.className = 'words';
  const chips = [...puzzle.placements].sort((a, b) => a.display.localeCompare(b.display, 'pt-BR'));
  const chipByWord = new Map<string, HTMLButtonElement>();
  for (const p of chips) {
    const chip = document.createElement('button');
    chip.className = 'chip';
    chip.dataset.word = p.word;
    chip.textContent = p.display;
    chip.addEventListener('click', () => pulseHint(view, puzzle, p));
    words.appendChild(chip);
    chipByWord.set(p.word, chip);
  }

  root.append(head, trace, area, words);

  applyFound(view, puzzle, foundFromSave(puzzle), trace, chipByWord);

  observer?.disconnect();
  const ro = new ResizeObserver(() => {
    sizeGrid(view, puzzle, found, area.clientWidth - 16, area.clientHeight - 16);
  });
  observer = ro;
  ro.observe(area);

  return root;
}

/** Restore the words found in this puzzle (same key as the saved progress). */
function foundFromSave(puzzle: Puzzle): FoundWord[] {
  const progress = getSave().progress;
  if (!progress || progress.key !== puzzle.key) return [];
  const found: FoundWord[] = [];
  progress.found.forEach((word, i) => {
    const p = puzzle.placements.find((pl) => pl.word === word);
    if (p) found.push({ word, cells: pathCells({ row: p.row, col: p.col }, p.dir, p.word.length - 1), colorIndex: i % 8 });
  });
  return found;
}

const found: FoundWord[] = [];

/** Draw restored pills/chips and set the idle trace text. */
function applyFound(view: GridView, puzzle: Puzzle, f: FoundWord[], trace: HTMLElement, chipByWord: Map<string, HTMLButtonElement>): void {
  found.length = 0;
  for (const w of f) {
    found.push(w);
    const chip = chipByWord.get(w.word);
    if (chip) {
      chip.classList.add('found');
      chip.disabled = true;
    }
  }
  redrawPills(view, found);
  trace.textContent = found.length > 0 ? '' : STR.dragHint;
}

/** Hint: pulse the first letter of the word (900ms). */
function pulseHint(view: GridView, puzzle: Puzzle, p: Placement): void {
  const cellEl = view.cellEls[p.row * puzzle.cols + p.col];
  if (!cellEl || cellEl.classList.contains('hint')) return;
  cellEl.classList.add('hint');
  setTimeout(() => cellEl.classList.remove('hint'), 900);
}

/** Persist a word found in the open puzzle (replaces progress if it belongs to another puzzle). */
export function recordFound(word: string): void {
  const save = getSave();
  const progress = save.progress && save.progress.key === save.progress.key
    ? { ...save.progress, found: [...save.progress.found, word] }
    : { key: save.progress?.key ?? '', found: [word] };
  saveState({ ...save, progress });
}

/** Mark a puzzle solved and clear its in-progress state. */
export function recordSolved(key: string): void {
  const save = getSave();
  saveState({ ...save, solved: save.solved.includes(key) ? save.solved : [...save.solved, key], progress: null });
}
