h1 { margin: 0; }
p { margin: 0; }

/* ---------- home ---------- */
.home { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.home-head { padding: 20px 16px 12px; display: flex; flex-direction: column; align-items: flex-start; }
.home-head h1 { font-size: 28px; }
.tagline { color: var(--muted); margin-top: 2px; }
.themes { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
.theme-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: 64px;
  padding: 0 16px;
  background: none;
  border: none;
  border-bottom: 1px solid var(--line);
  text-align: left;
}
.theme-row .emoji { font-size: 22px; }
.theme-text { display: flex; flex-direction: column; align-items: flex-start; line-height: 1.25; }
.theme-text span { color: var(--muted); font-size: 14px; }

/* ---------- puzzle ---------- */
.puzzle { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.puzzle-head { flex: 0 0 52px; display: flex; align-items: center; gap: 6px; padding: 0 8px; }
.icon-btn {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border: none;
  background: none;
  border-radius: 50%;
  font-size: 26px;
  line-height: 1;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.title { display: flex; flex-direction: column; align-items: flex-start; line-height: 1.2; }
.title span { color: var(--muted); font-size: 14px; }

.trace {
  flex: 0 0 44px;
  height: 44px;
  display: grid;
  place-items: center;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.grid-area {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px 12px;
}
.grid-paper { background: var(--surface); border-radius: var(--radius); padding: 8px; }
.grid { position: relative; touch-action: none; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }
.overlay { position: absolute; inset: 0; z-index: 0; pointer-events: none; }
.cells { display: grid; grid-template-columns: repeat(var(--cols), var(--cell)); position: relative; z-index: 1; }
.cell { display: grid; place-items: center; height: var(--cell); font-size: calc(var(--cell) * 0.52); font-weight: 700; line-height: 1; user-select: none; }
.cell.hint { animation: pulse 0.45s ease-in-out 2; box-shadow: inset 0 0 0 3px var(--hl); border-radius: 50%; }
@keyframes pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.18); } }

.pill { opacity: var(--pill-alpha); }
.pill.p0 { stroke: var(--p0); } .pill.p1 { stroke: var(--p1); } .pill.p2 { stroke: var(--p2); } .pill.p3 { stroke: var(--p3); }
.pill.p4 { stroke: var(--p4); } .pill.p5 { stroke: var(--p5); } .pill.p6 { stroke: var(--p6); } .pill.p7 { stroke: var(--p7); }
.active { stroke: var(--hl); opacity: var(--active-alpha); }

.words {
  flex: 0 0 auto;
  max-height: 34vh;
  overflow-y: auto;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  padding: 10px 12px calc(12px + env(safe-area-inset-bottom));
}
.chip {
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink);
  border-radius: 999px;
  padding: 6px 12px;
}
.chip.found { border-color: transparent; text-decoration: line-through; opacity: 0.8; }
.chip.p0 { background: var(--p0); } .chip.p1 { background: var(--p1); } .chip.p2 { background: var(--p2); } .chip.p3 { background: var(--p3); }
.chip.p4 { background: var(--p4); } .chip.p5 { background: var(--p5); } .chip.p6 { background: var(--p6); } .chip.p7 { background: var(--p7); }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
